public async Task<CustomerOrderStatusResponse> Handle(GetCustomerOrderStatusQuery query, CancellationToken cancellationToken)
    {
        var order = await CustomerCheckoutSupport.LoadOwnedOrderAsync(dbContext, currentUser, query.OrderUuid, cancellationToken);
        return new CustomerOrderStatusResponse(order.StatusId, order.Closed, CustomerCheckoutSupport.ResolveHomepageLink(order.TourTimeSlot!.Tour!, options.Value));
    }

