[HttpGet("{orderId}/status")]
    public Task<CustomerOrderStatusResponse> CheckOrderStatus(string orderId, CancellationToken cancellationToken)
    {
        return getCustomerOrderStatusQueryHandler.Handle(new GetCustomerOrderStatusQuery(orderId), cancellationToken);
    }

